export const seriesCourses = seriesDefinitions.map(definition => {
  const chapters = seriesDefinitions.filter(item => item.series === definition.series).sort((a, b) => a.chapter - b.chapter);
  const next = chapters.find(item => item.chapter > definition.chapter);
  return { ...createSeriesCourse(definition), series: { name: definition.series, chapter: definition.chapter, totalChapters: chapters.length, nextCourseId: next?.id } };
});
export const seriesOverview = seriesDefinitions.map(createSeriesOverview);
